  <div class="tf-grade">${ORDEM_MEDALHAS.map((m) => { const M = MEDALHAS[m], q = T[m] || 0, nv = nivelTrofeu(q); const prox = NIVEIS_TROFEU.find((t) => q < t.n); const ini = nv.atual ? nv.atual.n : 0;
    return `<div class="tf ${q ? '' : 'nada'}" style="--c:${nv.atual ? nv.atual.cor : '#334155'}"><i>${M.icone}</i><b>${M.nome}</b><small>${M.desc}</small><div class="xp"><i style="width:${prox ? Math.round(((q - ini) / (prox.n - ini)) * 100) : 100}%"></i></div><em>${q}× · ${nv.atual ? nv.atual.nome : 'bloqueada'}${prox ? ` → ${prox.nome} em ${prox.n}` : ' · máximo'}</em></div>`; }).join('')}</div>
